"/* ==========================================================================
   CAR VAULT — Page-Specific Styles (css/pages.css)
   Covers: Home Page, Explore Cars Page, and Car Details Page
   ========================================================================== */

/* ---------- 1. HOME PAGE ---------- */
.home-hero {
  padding: 36px 0 28px;
  background-color: var(--white);
  border-bottom: 1px solid var(--border-grey);
}

.home-hero-title {
  text-align: center;
  font-size: clamp(2rem, 4.2vw, 3.1rem);
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 22px;
  letter-spacing: -0.02em;
}

.hero-banner-box {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 2px solid var(--navy);
  box-shadow: var(--shadow-md);
  background-color: var(--navy);
}

.hero-banner-img {
  width: 100%;
  height: 410px;
  object-fit: cover;
}

.hero-stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin: 22px auto 24px;
  max-width: 780px;
}

.stat-box {
  background-color: var(--navy);
  color: var(--white);
  border: 1px solid var(--gold);
  border-radius: var(--radius-sm);
  padding: 14px 10px;
  text-align: center;
}

.stat-box strong {
  display: block;
  font-size: 1.35rem;
  color: var(--gold);
  font-weight: 800;
}

.stat-box span {
  font-size: 0.82rem;
  color: #e5e7eb;
  font-weight: 600;
}

.home-explore-cta-wrap {
  margin-top: 10px;
}

.home-explore-cta {
  width: 100%;
  padding: 16px 24px;
  font-size: 1.15rem;
  letter-spacing: 0.03em;
  box-shadow: var(--shadow-sm);
}

.home-section {
  padding: 40px 0 12px;
}

.section-title {
  font-size: 1.65rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 20px;
  border-left: 5px solid var(--gold);
  padding-left: 12px;
}

.featured-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

